/**
 * 同じキーでは 1 回だけ true を返す（記事内で最初のブロックだけ id を付ける、フッターは 1 つだけ等）。
 * render.php はブロックごとに include されるため、ファイル内の static 変数ではなく関数の static に持つ。
 *
 * REST の投稿一覧レスポンスでは the_content が 1 リクエスト中に複数の投稿分連続で走るため、
 * 呼び出し側は必ず投稿単位でキーを分ける（例: 'first-block:' . get_the_ID(), 'footer:' . get_the_ID()）。
 * 固定文字列だけをキーにすると 2 件目以降の投稿でフッター／id="phone-cta" が出なくなる。
 */
function madoguchi_blocks_phone_cta_once( $key ) {
	static $done = array();
	if ( isset( $done[ $key ] ) ) {
		return false;
	}
	$done[ $key ] = true;
	return true;
}

/**
 * 1 リクエスト内で通し番号を振る。同じ id の要素を二度出さないために使う。
 *
 * 記事に電話CTAブロックを複数置いた場合や、1 つのブロックで同じ店舗を 2 回選んだ場合、
 * 投稿ID＋店舗UUID だけではモーダルのチェックボックス id が衝突する。CSS の兄弟セレクタで
 * 開く仕組みなので、衝突すると別のカードのモーダルが開いてしまう。
 *
 * @return int 0 から始まる通し番号
 */
function madoguchi_blocks_phone_cta_seq() {
	static $seq = 0;
	return $seq++;
}

/**
 * API から受け取った QR の SVG を安全な要素・属性だけに絞って返す。
 * 自社 API の出力だが、記事 HTML に生で差し込むため許可リストを通す。
 * SVG でない・スクリプトを含む場合は空文字（＝QR を出さない）。
 */
function madoguchi_blocks_phone_cta_qr_svg( $svg ) {
	$svg = trim( (string) $svg );
	if ( '' === $svg || 0 !== strpos( $svg, '<svg' ) ) {
		return '';
	}
	if ( preg_match( '/<script|javascript:|\son[a-z]+\s*=/i', $svg ) ) {
		return '';
	}
	$shape = array(
		'd'               => array(),
		'x'               => array(),
		'y'               => array(),
		'width'           => array(),
		'height'          => array(),
		'fill'            => array(),
		'stroke'          => array(),
		'stroke-width'    => array(),
		'transform'       => array(),
		'shape-rendering' => array(),
	);
	return wp_kses( $svg, array(
		'svg'  => array(
			'xmlns'           => array(),
			'xmlns:xlink'     => array(),
			'version'         => array(),
			'viewbox'         => array(),
			'class'           => array(),
			'role'            => array(),
			'aria-label'      => array(),
			'width'           => array(),
			'height'          => array(),
			'shape-rendering' => array(),
			'fill'            => array(),
		),
		'g'    => $shape,
		'path' => $shape,
		'rect' => $shape,
	) );
}

/**
 * 表示テキスト用の許可リスト（RichText のインライン書式を活かす）。
 */
function madoguchi_blocks_phone_cta_kses( $html ) {
	return wp_kses( (string) $html, array(
		'br'     => array(),
		'strong' => array(),
		'em'     => array(),
		'a'      => array( 'href' => array(), 'target' => array(), 'rel' => array() ),
	) );
}
